def bfs_path(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for r in I for x in r); bg=cnt.most_common(1)[0][0]
    src=set((a,b) for a in range(H) for b in range(W) if I[a][b]==2)
    dst=set((a,b) for a in range(H) for b in range(W) if I[a][b]==3)
    seen={}; q=deque()
    for s in src: seen[s]=0; q.append(s)
    while q:
        x,y=q.popleft(); d=seen[(x,y)]
        if (x,y) in dst: break
        for dx in(-1,0,1):
            for dy in(-1,0,1):
                n=(x+dx,y+dy)
                if 0<=n[0]<H and 0<=n[1]<W and (I[n[0]][n[1]]==bg or n in src or n in dst) and n not in seen:
                    seen[n]=d+1; q.append(n)
    return set(seen)-src  # all visited bg cells

