def solve(I):
    H,W=len(I),len(I[0])
    cnt=Counter(x for r in I for x in r); bg=cnt.most_common(1)[0][0]
    bar2=[(a,b) for a in range(H) for b in range(W) if I[a][b]==2]
    bar3=[(a,b) for a in range(H) for b in range(W) if I[a][b]==3]
    O=[r[:] for r in I]
    # zone = cells 8-adjacent to bar3, except bar3 cells themselves (bar3 cells are the goal)
    zone=set()
    for (a,b) in bar3:
        for dx in(-1,0,1):
            for dy in(-1,0,1):
                p=(a+dx,b+dy)
                if 0<=p[0]<H and 0<=p[1]<W and p not in set(bar3): zone.add(p)
    src={(a,b) for a,b in bar2}
    dist={}
    q=deque(); dist={s:(0,None) for s in src}
    for s in src: q.append(s)
    while q:
        (x,y)=(q.popleft())
        d,mv=dist[(x,y)]
        if (x,y) in set(bar3): break
        for dx,dy in((0,1),(0,-1),(1,0),(-1,0)):
            n=(x+dx,y+dy)
            if not(0<=n[0]<H and 0<=n[1]<W) or I[n[0]][n[1]]!=bg or n in zone or n in set(bar2): continue
            if n not in dist or dist[n][0]>d+1:
                dist[n]=(d+1,mv); q.append(n)
    if len(dist)<max(1,len(bar2)): return None
    # reconstruct shortest path to first bar3 cell reached
    tgt=min(set(bar3), key=lambda p:dist.get(p,float('inf')))
    if tgt not in dist: return None
    path=[]; cur=tgt
    while cur not in src:
        path.append(cur)
        d_,mv=dist[cur]; prev=None
        for dx,dy in((0,1),(0,-1),(1,0),(-1,0)):
            n=(cur[0]+dx,cur[1]+dy)
            if n in src or (n in dist and dist[n][0]==d_-1): prev=n
        if prev is None: return None; cur=prev
    path.append(tgt)  # include bar3 cells? they're already 3. include bg cells on path only
    for (a,b) in path:
        if I[a][b]==bg: O[a][b]=3
    return O,path

